const TARGET='1'.repeat(40),NOW='2026-10-08T12:00:00.000Z';
// Retain the original 1/2/4 regression scenarios explicitly; new tests below cover the default SLA.
const selectDirect=(inv,a,state,o={})=>selectCurrent(inv,a,state,{rotationPolicy:'A',...o});
const options={rotationPolicy:'A',runId:'TEST-DEEP-001',chunkBytes:256,coverageBytes:12288,themeBytes:24576,maxTokens:256,maxUsd:5,maxTotalUsd:200};
async function fixture(fn){
 const root=fs.mkdtempSync(path.join(os.tmpdir(),'force-deep-test-'));
 try{git(root,['init','-q']);git(root,['config','user.name','Disposable mock']);git(root,['config','user.email','mock@example.invalid']);git(root,['config','core.autocrlf','false']);
  const write=(name,value)=>{const p=path.join(root,name);fs.mkdirSync(path.dirname(p),{recursive:true});fs.writeFileSync(p,value);};
  const source='// model source\r\nexport const x=1;\r\n';
  for(const [p,s]of Object.entries({'.gitignore':'research/claude-api-reviews/\n','model/source.js':source,'assets/app.js':source,'README.md':'# human methodology\n','unknown.zz':'unknown but readable\n','scripts/test_example.mjs':'// negative control source\n','scripts/run_tests.mjs':'// runner\n','scripts/test_catalog.json':'{}\n','scripts/build_public.py':'# build\n','Dockerfile':'FROM pinned\n','force_server.py':'# source\n','data/seed.js':'export const data={};\n','public/model/source.js':source,'research/example/analyze.mjs':'// generator\n','research/example/results/data.json':'{"a":1}\n','research/example/inputs.json':'{"method":"identity"}\n','scripts/fixtures/contract.json':'{"required":"input"}\n','research/example/fixtures/pop.csv':'team,value\nA,2\n','data/live-cache/cache.json':'{"payload":1}\n','vendor/upstream.js':'// third-party\n'}))write(p,s);
  write('image.png',Buffer.from([0,2,3]));write('odd.bin',Buffer.from([255,254]));write('large.md',('LONG UTF8 αβ🌟\r\n').repeat(1000));write('one-line.txt','🧪'.repeat(1000));
  git(root,['add','.']);git(root,['commit','-qm','target']);const target=git(root,['rev-parse','HEAD']).trim();git(root,['branch','-m','analysis']);
  const directState={...initialDirectState(inventory(root,target)),completedAudits:3};const built=()=>buildPlan(root,target,{...options,directState}),save=()=>{const b=built();return createRun(root,b,initialize(target,NOW),NOW);};await fn({root,target,write,built,save});
 }finally{assert(root.startsWith(path.join(os.tmpdir(),'force-deep-test-')));fs.rmSync(root,{recursive:true,force:true});}
}
function completedState(time='2026-10-01T12:00:00.000Z'){return completeCadence(initialize(TARGET,time),{verifiedComplete:true,apiCalls:1,passes:1,runId:'PAID-BASELINE',target:TARGET,createdAt:time,manifestHash:'2'.repeat(64),toolingHead:TARGET},time,true);}
function events(s,n,classification='SUBSTANTIVE'){for(let i=0;i<n;i++){const previousMain=s.integrations.at(-1)?.main??TARGET;s=recordIntegration(s,{id:'I-'+(s.integrations.length+1),time:'2026-10-02T12:00:00.000Z',main:(s.integrations.length+2).toString(16).padStart(40,'0'),previousMain,title:'Owner-authorized integration',classification,rationale:'Behavioral contract changed',tags:[]},NOW);}return s;}
function outcome(target,findings=[]){return {verdict:findings.some(f=>f.severity==='MINOR')?'ACCEPTED WITH MINORS':'ACCEPTED',summary:'Independent mocked review',findings,limitations:['Mock only'],scope:{start_sha:target,end_sha:target}};}
function finding(p,nature='ACTUAL DEFECT',severity='MINOR',evidence='specific observed source evidence'){return {severity,nature,affected_paths:[p],location:p+':1',evidence,impact:'Concrete contract risk',correction:'Bounded verification',confidence:'HIGH'};}
const mockKey='mock-'+'k'.repeat(40);
function deps(target,change={},counts={keys:0,calls:0},custom){return {environmentVerifier:()=>{},secretLoader:()=>{counts.keys++;return mockKey;},fetcher:async(_u,opt)=>{counts.calls++;const body=JSON.parse(opt.body);assert.equal(body.system[0].text,SYSTEM);assert(body.system[0].cache_control);assert.equal(body.system[1].text,DEEP_DOCTRINE);const raw={type:'message',id:'msg_mock',model:'claude-opus-5-5',stop_reason:'end_turn',content:[{type:'text',text:JSON.stringify(custom??outcome(target))}],usage:{input_tokens:100,output_tokens:50,cache_creation_input_tokens:0,cache_read_input_tokens:0},...change};return new Response(JSON.stringify(raw),{status:200,headers:{'request-id':'req_mock'}});}};}
function sendOptions(run,p,extra={}){return {send:true,toolingHead:run.plan.toolingHead,target:run.plan.target,manifestHash:run.plan.manifestHash,packetHash:p.packetSha256,maxUsd:5,maxTotalUsd:200,...extra};}

test('deterministic target Git inventory, post-target files never leak',()=>fixture(p=>{const a=p.built();p.write('post-target.js','POST_TARGET_SENTINEL');git(p.root,['add','.']);git(p.root,['commit','-qm','tooling after target']);p.write('README.md','DIRTY_WORKTREE_SENTINEL');const b=p.built();assert.equal(a.manifestText,b.manifestText);assert.deepEqual([...a.packets],[...b.packets]);assert(!b.manifest.files.some(f=>f.path==='post-target.js'));assert(![...b.packets.values()].some(s=>s.includes('DIRTY_WORKTREE_SENTINEL')));}));
for(const name of ['model/source.js','README.md','scripts/test_example.mjs','scripts/run_tests.mjs','scripts/test_catalog.json','Dockerfile','force_server.py','data/seed.js','research/example/analyze.mjs','research/example/inputs.json','scripts/fixtures/contract.json','large.md','one-line.txt'])test('actual content eligible: '+name,()=>fixture(p=>{const f=p.built().manifest.files.find(f=>f.path===name);assert(f.eligible);assert(f.ranges.length>0);}));
for(const [name,reason]of [['image.png','BINARY_MEDIA'],['odd.bin','BINARY_MEDIA'],['data/live-cache/cache.json','RAW_PROVIDER_CACHE'],['research/example/fixtures/pop.csv','FIXTURE_POPULATION'],['research/example/results/data.json','GENERATED_EVIDENCE'],['public/model/source.js','EXACT_PUBLIC_MIRROR'],['vendor/upstream.js','VENDORED_THIRD_PARTY']])test('explicit exclusion: '+reason+' '+name,()=>fixture(p=>{const f=p.built().manifest.files.find(f=>f.path===name);assert(!f.eligible);assert.equal(f.exclusionReason,reason);assert(EXCLUSIONS[reason]);}));
test('unknown readable files surface ambiguity and stay covered',()=>fixture(p=>{const f=p.built().manifest.files.find(f=>f.path==='unknown.zz');assert(f.ambiguity.length);assert(f.eligible);}));
test('unproven public mirror and generated evidence remain eligible',()=>fixture(p=>{p.write('public/model/source.js','different generated content');p.write('research/no-source/results/file.json','{}');git(p.root,['add','.']);git(p.root,['commit','-qm','different mirror']);const x=inventory(p.root,git(p.root,['rev-parse','HEAD']).trim());assert(x.files.find(f=>f.path==='public/model/source.js').eligible);assert(x.files.find(f=>f.path==='research/no-source/results/file.json').eligible);}));
test('symlink disposition is explicit and not followed',{skip:process.platform==='win32'},()=>fixture(p=>{fs.symlinkSync('../README.md',path.join(p.root,'model/link'));git(p.root,['add','.']);git(p.root,['commit','-qm','link']);const x=inventory(p.root,git(p.root,['rev-parse','HEAD']).trim());assert.equal(x.files.find(f=>f.path==='model/link').exclusionReason,'NONREGULAR_OBJECT');}));
test('credential-pattern planning refuses content without key lookup',()=>fixture(p=>{p.write('secret-example.txt','sk'+'-ant-'+ 'z'.repeat(30));git(p.root,['add','.']);git(p.root,['commit','-qm','synthetic credential']);assert.throws(()=>inventory(p.root,git(p.root,['rev-parse','HEAD']).trim()),/Credential-pattern/);}));
for(const [name,b]of [['CRLF',Buffer.from('a\r\nb\r\n')],['BOM',Buffer.from('\ufeffa\r\n')],['long UTF8 line',Buffer.from('🌟α'.repeat(100))],['empty',Buffer.alloc(0)],['long ascii',Buffer.from('q'.repeat(100))]])test('lossless deterministic splitting: '+name,()=>{const c=chunkBuffer(b,7);assert.deepEqual(c,chunkBuffer(b,7));assert(Buffer.concat(c.map(c=>Buffer.from(c.text))).equals(b));assert(c.every(c=>c.end-c.start<=7));});
test('every eligible byte covered, chunks assigned correctly across boundaries',()=>fixture(p=>{const a=p.built(),inv=inventory(p.root,p.target);assert(validateCoverage(a.manifest,a.packets,inv));assert(a.manifest.files.find(f=>f.path==='large.md').contentShards.length>1);for(const d of a.plan.passes){assert(d.packetBytes<= (d.kind==='CONTENT'?options.coverageBytes:options.themeBytes));assert(d.packetBytes<HARD_LIMIT-65536);assert.equal(hash(a.packets.get(d.id)),d.packetSha256);}assert.equal(a.plan.summary.inventoryCoveragePercent,100);}));
for(const defect of ['missing-file','excluded-eligible','unknown-reason','coverage-gap','altered-chunk'])test('coverage checker catches '+defect,()=>fixture(p=>{const a=p.built(),inv=inventory(p.root,p.target),m=structuredClone(a.manifest),packets=new Map(a.packets),f=m.files.find(f=>f.path==='README.md');if(defect==='missing-file')m.files.pop();if(defect==='excluded-eligible'){f.eligible=false;f.disposition='EXCLUDED';f.exclusionReason='too_large';}if(defect==='unknown-reason')m.files.find(f=>!f.eligible).exclusionReason='OTHER';if(defect==='coverage-gap')f.ranges[0].start++;if(defect==='altered-chunk'){const body=JSON.parse(packets.get(f.ranges[0].shard));body.content.find(c=>c.path===f.path).text='WRONG';packets.set(f.ranges[0].shard,json(body));}assert.throws(()=>validateCoverage(m,packets,inv));}));
test('four complementary themes expose complete map and selected bytes exactly once',()=>fixture(p=>{const a=p.built(),contents=inventory(p.root,p.target).contents;for(const theme of THEMES){const ds=a.plan.passes.filter(p=>p.theme===theme.id);assert(ds.length);for(const d of ds)assert.equal(JSON.parse(a.packets.get(d.id)).repoMap.rows.length,a.manifest.files.length);}for(const f of a.manifest.files.filter(f=>f.directSelected)){const cs=[...a.packets.values()].flatMap(x=>JSON.parse(x).content).filter(c=>c.path===f.path);assert(Buffer.concat(cs.map(c=>Buffer.from(c.text))).equals(contents.get(f.path)));}}));
test('planning fails on overhead or budgets, never silently drops eligible content',()=>fixture(p=>{assert.throws(()=>buildPlan(p.root,p.target,{...options,directState:p.built().plan.options.directState,chunkBytes:32768,themeBytes:8192}),/OVERHEAD|CHUNK/);assert(buildPlan(p.root,p.target,{...options,maxTotalUsd:0.00001}).plan.budgetWarnings.some(w=>w.includes('TOTAL GUARD')));assert.throws(()=>buildPlan(p.root,p.target,{...options,maxUsd:0.00001}),/PER_CALL/);assert.throws(()=>buildPlan(p.root,p.target,{...options,themeBytes:HARD_LIMIT}),/MARGIN/);}));

test('bootstrap due honestly, no synthetic historical completion',()=>{const s=initialize(TARGET,NOW);assert.equal(s.lastCompletedDeepReview,null);assert.match(s.lastEvaluation.reasons[0],/INITIAL BASELINE/);});
test('five substantive integration events count independently of commit counts',()=>{assert.equal(evaluate(events(completedState(),4),'2026-10-03T12:00:00.000Z').status,'NOT DUE');assert.equal(evaluate(events(completedState(),5),'2026-10-03T12:00:00.000Z').status,'DEEP REVIEW DUE');});
test('housekeeping excluded, ambiguous threshold explicit, reclassification resolves',()=>{let s=events(completedState(),4);s=events(s,1,'AMBIGUOUS');s=events(s,2,'HOUSEKEEPING');const time='2026-10-03T12:00:00.000Z';assert.match(evaluate(s,time).status,/CADENCE AMBIGUOUS/);assert.equal(evaluate(classifyIntegration(s,'I-5','HOUSEKEEPING','Closeout only',NOW),time).status,'NOT DUE');assert.equal(evaluate(classifyIntegration(s,'I-5','SUBSTANTIVE','Behavioral gate',NOW),time).status,'DEEP REVIEW DUE');assert.equal(evaluate(s,NOW).status,'DEEP REVIEW DUE');});
test('seven Chicago calendar dates, not 168 hours; timezone crossing',()=>{const s=completedState('2026-10-01T23:30:00.000Z');assert.equal(evaluate(s,'2026-10-08T05:00:00.000Z').calendarDaysSinceCompletion,7);assert.equal(evaluate(s,'2026-10-08T04:59:59.000Z').status,'NOT DUE');assert.equal(chicagoDate('2026-10-08T04:00:00.000Z'),'2026-10-07');});
test('calendar cadence handles daylight saving independently of elapsed suppression',()=>{const s=completedState('2026-10-26T05:30:00.000Z');assert.equal(evaluate(s,'2026-11-02T06:00:00.000Z').calendarDaysSinceCompletion,7);assert.equal(chicagoDate('2026-11-01T06:30:00.000Z'),chicagoDate('2026-11-01T07:30:00.000Z'));});
test('routine suppressed for rolling elapsed 24h, exactly 24h allowed',()=>{let s=completedState('2026-10-02T11:00:00.000Z');s=events(s,5);assert.equal(evaluate(s,'2026-10-03T10:59:59.000Z').status,'NOT DUE');assert.equal(evaluate(s,'2026-10-03T11:00:00.000Z').status,'DEEP REVIEW DUE');});
for(const category of Object.keys(TRIGGERS))test('mandatory '+category+' bypasses routine suppression explicitly',()=>{const time='2026-10-08T13:00:00.000Z',s=recordTrigger(completedState(NOW),{id:'TRIGGER',category,rationale:'Explicit owner classified major architecture change',time},time),e=evaluate(s,time);assert.equal(e.status,'DEEP REVIEW DUE');assert.match(e.reasons[0],/MANDATORY.*<24H/);assert.equal(evaluate(clearTrigger(s,'TRIGGER','Owner cleared',time),time).status,'NOT DUE');});
test('unknown triggers, duplicate events and future events fail',()=>{assert.throws(()=>recordTrigger(completedState(),{id:'T',category:'UNKNOWN',rationale:'Unclassified',time:NOW},NOW));let s=events(completedState(),1);assert.throws(()=>recordIntegration(s,s.integrations[0],NOW),/DUPLICATE/);assert.throws(()=>evaluate(s,'2026-10-01T12:00:00.000Z'),/FUTURE/);});
test('completion resets covered events, retains integrations/triggers after reviewed snapshot',()=>{let s=events(completedState(),5);s=recordTrigger(s,{id:'NEW',category:'HISTORICAL',rationale:'New after snapshot',time:'2026-10-08T11:00:00.000Z'},NOW);const next=completeCadence(s,{verifiedComplete:true,apiCalls:2,passes:2,runId:'ALL-PASSES',target:TARGET,createdAt:'2026-10-03T12:00:00.000Z',manifestHash:'2'.repeat(64),toolingHead:TARGET},NOW,true,{isAncestor:()=>true});assert.equal(next.integrations.length,0);assert.equal(next.activeMandatoryTriggers.length,1);assert.equal(next.lastCompletedDeepReview.date,'2026-10-08');});
for(const bad of [{verifiedComplete:false},{verifiedComplete:true,apiCalls:0,passes:1},{verifiedComplete:true,apiCalls:1,passes:0}])test('dry/failed/incomplete cannot reset cadence '+JSON.stringify(bad),()=>{const s=initialize(TARGET,NOW);assert.throws(()=>completeCadence(s,bad,NOW,true));assert.equal(s.lastCompletedDeepReview,null);});
test('completion requires explicit confirmation and prevents duplicate run record',()=>{const s=initialize(TARGET,NOW),r={verifiedComplete:true,apiCalls:1,passes:1,runId:'R',target:TARGET,createdAt:NOW,manifestHash:'2'.repeat(64),toolingHead:TARGET};assert.throws(()=>completeCadence(s,r,NOW));const n=completeCadence(s,r,NOW,true);assert.throws(()=>completeCadence(n,r,NOW,true),/ALREADY/);});
test('run plan persistence and idempotent reconstruction, no overwrite',()=>fixture(p=>{const r=p.save();assert.deepEqual(loadRun(p.root,r.plan.runId).plan,r.plan);assert.throws(()=>p.save(),/RUN_ALREADY_EXISTS/);assert(status(r).pending.length);}));
for(const mode of [{},{send:false}])test('default/dry pass never reads key or requests '+JSON.stringify(mode),()=>fixture(async p=>{const r=p.save(),counts={keys:0,calls:0};const result=await runPass(p.root,r.plan.runId,r.plan.passes[0].id,mode,deps(p.target,{},counts));assert.equal(result.mode,'DRY_RUN');assert.deepEqual(counts,{keys:0,calls:0});assert.equal(loadRun(p.root,r.plan.runId).state.passes[r.plan.passes[0].id].status,'PENDING');assert.throws(()=>verifyCompletion(p.root,r.plan.runId),/INCOMPLETE/);}));
