test('environment pins checked before key access and request intent',()=>fixture(async p=>{const r=p.save(),pass=r.plan.passes[0],counts={keys:0,calls:0};await assert.rejects(runPass(p.root,r.plan.runId,pass.id,sendOptions(r,pass),{...deps(p.target,{},counts),environmentVerifier:()=>{throw new Error('MAIN_MOVED');}}),/MAIN_MOVED/);assert.equal(counts.keys,0);}));
test('one send produces one request, complete pass cannot resend, resume omits completed',()=>fixture(async p=>{const r=p.save(),pass=r.plan.passes[0],counts={keys:0,calls:0};const result=await runPass(p.root,r.plan.runId,pass.id,sendOptions(r,pass),deps(p.target,{},counts));assert.equal(result.status,'COMPLETED');assert.deepEqual(counts,{keys:1,calls:1});await assert.rejects(runPass(p.root,r.plan.runId,pass.id,sendOptions(r,pass),deps(p.target,{},counts)),/CANNOT_RESEND/);assert.equal(counts.calls,1);const resumed=loadRun(p.root,r.plan.runId);assert(!status(resumed).pending.includes(pass.id));assert.equal(status(resumed).rows.find(p=>p.id===pass.id).status,'COMPLETED');assert.throws(()=>verifyCompletion(p.root,r.plan.runId),/INCOMPLETE/);}));
for(const [label,change,want]of [['truncation',{stop_reason:'max_tokens'},'TRUNCATED_RESPONSE'],['wrong model',{model:'other-model'},'INVALID_RESPONSE'],['refusal',{stop_details:{type:'refusal'}},'INVALID_RESPONSE'],['wrong response schema',{type:'other'},'INVALID_RESPONSE']])test(label+' persists incomplete and does not auto retry',()=>fixture(async p=>{const r=p.save(),pass=r.plan.passes[0],counts={keys:0,calls:0},result=await runPass(p.root,r.plan.runId,pass.id,sendOptions(r,pass),deps(p.target,change,counts));assert.equal(result.status,want);assert.equal(counts.calls,1);const next=loadRun(p.root,r.plan.runId);assert(status(next).ownerActionRequired.includes(pass.id));assert.throws(()=>verifyCompletion(p.root,r.plan.runId),/INCOMPLETE/);await assert.rejects(runPass(p.root,r.plan.runId,pass.id,sendOptions(r,pass),deps(p.target,{},counts)),/OWNER_ACTION_REQUIRED/);assert.equal(counts.calls,1);if(label==='truncation')assert.equal(result.telemetry.stopReason,'max_tokens');}));
test('network failure redacts exception, no automatic retry, explicit retry retained and budgeted',()=>fixture(async p=>{const r=p.save(),pass=r.plan.passes[0],counts={keys:0,calls:0};const d=deps(p.target,{},counts);d.fetcher=async()=>{counts.calls++;throw new Error(mockKey);};const first=await runPass(p.root,r.plan.runId,pass.id,sendOptions(r,pass),d);assert.equal(first.status,'REQUEST_FAILED');assert(!fs.readFileSync(path.join(r.dir,first.resultPath),'utf8').includes(mockKey));await assert.rejects(runPass(p.root,r.plan.runId,pass.id,sendOptions(r,pass,{retry:true,retryReason:'Owner checked failed attempt billing',maxTotalUsd:r.plan.estimatedCeilingUsd}),deps(p.target,{},counts)),/TOTAL_COST/);const second=await runPass(p.root,r.plan.runId,pass.id,sendOptions(r,pass,{retry:true,retryReason:'Explicit owner retry after billing inspection'}),deps(p.target,{},counts));assert.equal(second.status,'COMPLETED');assert.equal(loadRun(p.root,r.plan.runId).state.passes[pass.id].attempts.length,2);assert.equal(counts.calls,2);}));
test('missing secret safe result, zero requests; no plaintext persisted',()=>fixture(async p=>{const r=p.save(),pass=r.plan.passes[0],counts={keys:0,calls:0},d=deps(p.target,{},counts);d.secretLoader=()=>{counts.keys++;throw new Error(mockKey);};const result=await runPass(p.root,r.plan.runId,pass.id,sendOptions(r,pass),d);assert.equal(result.status,'REQUEST_FAILED');assert.equal(result.apiCalls,0);assert.equal(counts.calls,0);assert(!fs.readFileSync(path.join(r.dir,result.resultPath),'utf8').includes(mockKey));}));
