const environmentCodes={head:'TOOLING_HEAD_CHANGED',dirty:'CLEAN_TOOLING_WORKTREE_REQUIRED',main:'SEND_FROM_OFF_MAIN_TOOLING_WORKTREE','local-main':'TARGET_NOT_ANCESTOR_OF_LOCAL_MAIN','tracking-main':'TARGET_NOT_ANCESTOR_OF_TRACKING_MAIN','remote-main':'TARGET_NOT_ANCESTOR_OF_REMOTE_MAIN',origin:'WRONG_FORCE_ORIGIN',pins:'EXACT_SEND_PINS_REQUIRED',target:'TARGET_OBJECT_UNAVAILABLE'};
function environmentFixture(variant='ok',advanced=false){const plan={toolingHead:TARGET,target:TARGET,manifestHash:'2'.repeat(64)},opts={toolingHead:TARGET,target:TARGET,manifestHash:'2'.repeat(64)},newer='f'.repeat(40);if(variant==='pins')opts.manifestHash='3'.repeat(64);const fake=(_root,args)=>{const key=args.join(' ');if(key==='rev-parse HEAD')return variant==='head'?'0'.repeat(40):TARGET;if(key==='symbolic-ref --short HEAD')return variant==='main'?'main':'codex/tooling';if(key.startsWith('status '))return variant==='dirty'?' M changed.js':'';if(key==='rev-parse refs/heads/main')return variant==='local-main'?'0'.repeat(40):advanced?newer:TARGET;if(key==='rev-parse refs/remotes/origin/main')return variant==='tracking-main'?'0'.repeat(40):advanced?newer:TARGET;if(key==='remote get-url origin')return variant==='origin'?'https://github.com/other/repo.git':'https://github.com/pfoeller/force-nfl.git';if(key==='ls-remote origin refs/heads/main')return (variant==='remote-main'?'0'.repeat(40):advanced?newer:TARGET)+'\trefs/heads/main';if(args[0]==='rev-parse'&&key.endsWith('^{commit}')){if(variant==='target'&&args[1]===TARGET+'^{commit}')throw Error('missing');return args[1].slice(0,-9);}if(args[0]==='merge-base'){if(args.at(-1)==='0'.repeat(40))throw Error('not ancestor');return '';}assert.fail('unexpected command '+key);};return {plan,opts,fake};}
for(const variant of ['ok',...Object.keys(environmentCodes)])test('pre-send environment '+variant+' independently checked',()=>{const {plan,opts,fake}=environmentFixture(variant);if(variant==='ok')assert.equal(verifySendEnvironment('.',plan,opts,{git:fake,nodeVersion:'24.19.0'}).mainAdvanced,false);else assert.throws(()=>verifySendEnvironment('.',plan,opts,{git:fake,nodeVersion:'24.19.0'}),new RegExp(environmentCodes[variant]));});


