test('production runtime remains pinned while unrelated negative guards are independently testable',()=>{const {plan,opts,fake}=environmentFixture('dirty');assert.throws(()=>verifySendEnvironment('.',plan,opts,{git:fake,nodeVersion:'22.0.0'}),/PINNED_NODE_24_19_0_REQUIRED/);assert.throws(()=>verifySendEnvironment('.',plan,opts,{git:fake,nodeVersion:'24.19.0'}),/CLEAN_TOOLING_WORKTREE_REQUIRED/);});
test('environment guard mutation disabling dirty-worktree detection is caught',()=>fixture(async p=>{const file=new URL('./run.mjs',import.meta.url);let code=fs.readFileSync(file,'utf8');const anchor="fail(inspect(root,['status','--porcelain','--untracked-files=normal']).trim()==='','CLEAN_TOOLING_WORKTREE_REQUIRED')";assert(code.includes(anchor));code=code.replace(anchor,'void 0').replace(/from '(\.\.?\/[^']+)'/g,(_,v)=>'from '+JSON.stringify(new URL(v,file).href));const name=path.join(p.root,'mutated-environment.mjs');fs.writeFileSync(name,code);const mutant=await import(pathToFileURL(name)),{plan,opts,fake}=environmentFixture('dirty');assert.throws(()=>assert.throws(()=>mutant.verifySendEnvironment('.',plan,opts,{git:fake,nodeVersion:'24.19.0'}),/CLEAN_TOOLING_WORKTREE_REQUIRED/),/Missing expected exception/);}));
test('plan pins current main but send permits immutable ancestor target after main advances',()=>{const {plan,opts,fake}=environmentFixture('ok',true);assert.throws(()=>verifyPlanTarget('.',TARGET,{git:fake}),/TARGET_MAIN_MOVED_AT_PLAN/);const state=verifySendEnvironment('.',plan,opts,{git:fake,nodeVersion:'24.19.0'});assert(state.mainAdvanced);assert.equal(state.target,TARGET);assert.match(state.message,/CURRENT MAIN ADVANCED — REVIEW REMAINS PINNED TO/);assert.equal(verifyPlanTarget('.',TARGET,{git:environmentFixture().fake}),TARGET);});
test('paid mock audit finishes pinned target after main advances; newer event remains outstanding',()=>fixture(async p=>{const r=p.save(),counts={keys:0,calls:0};for(const pass of r.plan.passes)await runPass(p.root,r.plan.runId,pass.id,sendOptions(r,pass),{...deps(p.target,{},counts),environmentVerifier:()=>({mainAdvanced:true,target:p.target,message:'CURRENT MAIN ADVANCED — REVIEW REMAINS PINNED TO '+p.target}),notify:()=>{}});p.write('newer.txt','newer main event');git(p.root,['add','.']);git(p.root,['commit','-qm','newer main']);const newer=git(p.root,['rev-parse','HEAD']).trim();let state={...initialize(p.target,'2026-10-01T12:00:00.000Z'),directReview:r.plan.options.directState};state=recordIntegration(state,{id:'LATER',previousMain:p.target,main:newer,time:'2026-10-02T12:00:00.000Z',title:'Synthetic later integration',classification:'SUBSTANTIVE',rationale:'Must remain unreviewed',tags:['HISTORICAL']},NOW);const next=completeCadence(state,verifyCompletion(p.root,r.plan.runId),NOW,true,{isAncestor:(e,t)=>integrationAncestry(p.root,e,t)});assert.equal(next.lastCompletedDeepReview.main,p.target);assert.equal(next.integrations[0].main,newer);assert(next.triggers[0].active);assert.equal(next.completionHistory[0].coveredIntegrations.length,0);assert.equal(counts.calls,r.plan.passes.length);}));
test('completion ancestry wins over late registration timestamps and rejects missing/unrelated objects',()=>fixture(p=>{p.write('next.md','included');git(p.root,['add','.']);git(p.root,['commit','-qm','included target']);const target=git(p.root,['rev-parse','HEAD']).trim(),event={id:'INCLUDED',previousMain:p.target,main:target,time:'2026-10-08T11:00:00.000Z',title:'Late-recorded included event',classification:'SUBSTANTIVE',rationale:'Ancestry wins',tags:['HISTORICAL']};let state=recordIntegration(initialize(p.target,'2026-10-01T12:00:00.000Z'),event,NOW);const verified={verifiedComplete:true,apiCalls:1,passes:1,runId:'PINNED',target,createdAt:'2026-10-02T12:00:00.000Z',manifestHash:'2'.repeat(64),toolingHead:TARGET};const next=completeCadence(state,verified,NOW,true,{isAncestor:(e,t)=>integrationAncestry(p.root,e,t)});assert.equal(next.integrations.length,0);assert(!next.triggers[0].active);assert.throws(()=>completeCadence(state,verified,NOW,true),/ANCESTRY_VERIFIER_REQUIRED/);assert.throws(()=>integrationAncestry(p.root,{...event,main:'0'.repeat(40)},target),/SHA_UNAVAILABLE/);git(p.root,['checkout','--orphan','unrelated']);git(p.root,['rm','-rf','.']);p.write('unrelated.txt','orphan');git(p.root,['add','.']);git(p.root,['commit','-qm','unrelated']);const unrelated=git(p.root,['rev-parse','HEAD']).trim();assert.throws(()=>integrationAncestry(p.root,event,unrelated),/TOPOLOGY_AMBIGUOUS/);}));
const driverFile=(bytes,reasons,tier=3)=>({bytes,tier,directSelected:true,selectionReasons:reasons});
for(const [name,files,expected,trigger]of [['deadline tiny risk',[driverFile(10000,['OVERDUE_DIRECT_REVIEW']),driverFile(10,['IMPLEMENTER_DECLARED_RISK: x'])],'OVERDUE_ROTATION',false],['risk heavy',[driverFile(10000,['IMPLEMENTER_DECLARED_RISK: x']),driverFile(10,['OVERDUE_DIRECT_REVIEW'])],'IMPLEMENTER_RISK',false],['changed heavy',[driverFile(10000,['CHANGED_SINCE_LAST_COMPLETED_TARGET']),driverFile(10,['IMPLEMENTER_DECLARED_RISK: x'])],'CHANGED_CONTENT',false],['mandatory trigger',[driverFile(10000,['CHANGED_SINCE_LAST_COMPLETED_TARGET'])],'CHANGED_CONTENT',true],['mixed',[driverFile(300,['LOCAL_TRUST']),driverFile(200,['OVERDUE_DIRECT_REVIEW']),driverFile(100,['IMPLEMENTER_RISK_CONTEXT: x'])],'STATIC_RISK',false]])test('cost drivers '+name,()=>{const result=costDrivers(files,{mandatoryTrigger:trigger});assert.equal(result.primaryDriver,expected);assert.equal(Object.values(result.byDriver).reduce((n,d)=>n+d.exclusiveOriginalBytes,0),result.selectedOriginalBytes);assert.equal(result.allMaterialDrivers.includes('MANDATORY_TRIGGER'),trigger);assert(Object.values(result.byDriver).every(d=>d.incrementalCeilingUsd===null));});
test('optional rotation order is never/age/hash, not path order, and reproducible for oversized heads',()=>{const state={files:{a:{lastAudit:8},z:{lastAudit:null},m:{lastAudit:2}}},periods={2:4,3:12},list=[{path:'a',tier:3},{path:'z',tier:3},{path:'m',tier:3}];assert.deepEqual([...list].sort(rotationCompare(state,periods,10,TARGET)).map(f=>f.path),['z','m','a']);assert.deepEqual([...list].reverse().sort(rotationCompare(state,periods,10,TARGET)).map(f=>f.path),['z','m','a']);assert.notDeepEqual([...list].sort(rotationCompare(state,periods,10,TARGET,'PATH_REFERENCE')).map(f=>f.path),['z','m','a']);});
test('scenario design changes every/most audits, preserves quiet reference and adds burst',()=>fixture(p=>{const inv=inventory(p.root,p.target),baskets=representativeChanges(inv),elevated=['model/source.js'];for(const scenario of SCENARIOS){const rows=Array.from({length:12},(_,i)=>scenarioCycle(scenario,i+1,baskets,elevated));const n=rows.filter(r=>r.changed.length).length;if(scenario==='CHANGE_EVERY')assert.equal(n,11);if(scenario==='CHANGE_MOST')assert.equal(n,8);if(scenario==='QUIET_REFERENCE')assert.equal(n,3);if(scenario==='BURSTY')assert(rows[5].mandatoryTrigger&&n>6);assert.equal(rows[0].changed.length,0);}}));
test('change-heavy private simulations retain deadlines for D and E and do not modify initial ledger',()=>fixture(p=>{const state=initialDirectState(inventory(p.root,p.target)),snapshot=json(state);for(const policy of ['D','E']){const result=simulateScenario(p.root,p.target,state,{scenario:'CHANGE_EVERY',rotationPolicy:policy,cycles:12,options});assert(result.firstFullSweepAudit<=12);assert.equal(result.rows.filter(r=>r.changedPaths.length).length,11);assert(result.rows.every(r=>r.overdueAfterCompletion===0&&r.tier1Percent===100));assert.equal(result.apiCalls,0);assert.equal(json(state),snapshot);assert.equal(result.audit12.neverReviewedAfter,0);}}));
for(const mode of ['exists','open','write','callback','success'])test('lock error and cleanup '+mode,async()=>{const calls=[],io={openSync:()=>{calls.push('open');if(mode==='exists')throw Object.assign(Error(),{code:'EEXIST'});if(mode==='open')throw Object.assign(Error(),{code:'EACCES'});return 7;},writeSync:()=>{calls.push('write');if(mode==='write')throw Object.assign(Error(),{code:'ENOSPC'});},closeSync:fd=>{assert.equal(fd,7);calls.push('close');},unlinkSync:()=>{calls.push('unlink');}};if(mode==='exists')assert.throws(()=>withLock('synthetic',()=>{},io),/run lock exists/);else if(mode==='open')assert.throws(()=>withLock('synthetic',()=>{},io),/LOCK_OPEN_FAILED: EACCES/);else if(mode==='write'){assert.throws(()=>withLock('synthetic',()=>{},io),/LOCK_INITIALIZATION_FAILED: ENOSPC/);assert.deepEqual(calls,['open','write','close','unlink']);}else{const work=()=>{if(mode==='callback')throw Error('callback failure');return 42;};if(mode==='callback')await assert.rejects(withLock('synthetic',work,io),/callback failure/);else assert.equal(await withLock('synthetic',work,io),42);assert.deepEqual(calls,['open','write','close','unlink']);}});
test('budget guards derive canonical warning extraordinary and absolute limits',()=>{authorizeBudget(BUDGET_POLICY.warningUsd,{});assert.throws(()=>authorizeBudget(BUDGET_POLICY.warningUsd+.01),/OVER_10/);assert.throws(()=>authorizeBudget(BUDGET_POLICY.extraordinaryAuthorizationUsd,{budgetOverride:true,overrideReason:'Synthetic owner override'}),/EXTRAORDINARY/);assert.throws(()=>authorizeBudget(BUDGET_POLICY.absoluteToolMaximumUsd+1),/ABSOLUTE/);});
